import { applyTeacherReview } from '../teachers/teacher-request.js';

export const WORK_DAG_STATUS = Object.freeze({
  RUNNING: 'RUNNING',
  WAITING: 'WAITING',
  COMPLETED: 'COMPLETED',
  BLOCKED: 'BLOCKED',
});

export const WORK_NODE_STATUS = Object.freeze({
  PENDING: 'PENDING',
  RUNNING: 'RUNNING',
  WAITING_TEACHER: 'WAITING_TEACHER',
  COMPLETED: 'COMPLETED',
  FAILED: 'FAILED',
  BLOCKED: 'BLOCKED',
});

const NODE_KINDS = new Set(['TASK', 'AUGMENTIO', 'TEACHER']);
const SECRET_KEY = /(secret|token|password|authorization|cookie|api[_-]?key|otp|private[_-]?key|credential)/i;
const SECRET_VALUE = /(bearer\s+[a-z0-9._~+/=-]{8,}|\bsk-[a-z0-9_-]{8,}|\bgh[pousr]_[a-z0-9]{12,})/i;

function clean(value, depth = 0) {
  if (depth > 6) return '[TRUNCATED]';
  if (value == null || typeof value === 'boolean' || typeof value === 'number') return value;
  if (typeof value === 'string') return SECRET_VALUE.test(value) ? '[REDACTED]' : value.slice(0, 12000);
  if (Array.isArray(value)) return value.slice(0, 100).map((item) => clean(item, depth + 1));
  if (typeof value === 'object') {
    const out = {};
    for (const [key, item] of Object.entries(value).slice(0, 120)) {
      if (SECRET_KEY.test(key)) continue;
      out[key] = clean(item, depth + 1);
    }
    return out;
  }
  return String(value).slice(0, 12000);
}

function stable(value) {
  if (Array.isArray(value)) return `[${value.map(stable).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stable(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

async function sha256(value) {
  const bytes = new TextEncoder().encode(value);
  const digest = await crypto.subtle.digest('SHA-256', bytes);
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

function unsignedDag(dag) {
  const value = clean(dag);
  delete value.integrity_sha256;
  return value;
}

async function signDag(dag) {
  const unsigned = unsignedDag(dag);
  return { ...unsigned, integrity_sha256: await sha256(stable(unsigned)) };
}

export async function verifyWorkDag(dag) {
  validateWorkDag(dag);
  const supplied = dag?.integrity_sha256;
  if (!supplied) throw Object.assign(new Error('WORK_DAG_INTEGRITY_REQUIRED'), { code: 'WORK_DAG_INTEGRITY_REQUIRED' });
  const unsigned = unsignedDag(dag);
  const expected = await sha256(stable(unsigned));
  if (expected !== supplied) throw Object.assign(new Error('WORK_DAG_INTEGRITY_MISMATCH'), { code: 'WORK_DAG_INTEGRITY_MISMATCH' });
  return true;
}

function assertNoCycles(nodes) {
  const byId = new Map(nodes.map((node) => [node.id, node]));
  const visiting = new Set();
  const visited = new Set();
  function visit(id) {
    if (visited.has(id)) return;
    if (visiting.has(id)) throw Object.assign(new Error('WORK_DAG_CYCLE'), { code: 'WORK_DAG_CYCLE' });
    visiting.add(id);
    for (const dep of byId.get(id)?.depends_on || []) visit(dep);
    visiting.delete(id);
    visited.add(id);
  }
  for (const node of nodes) visit(node.id);
}

export function validateWorkDag(dag) {
  if (!dag || dag.schema !== 'mel.work-dag' || dag.version !== 1 || !dag.id || !dag.job_id) {
    throw Object.assign(new Error('WORK_DAG_INVALID'), { code: 'WORK_DAG_INVALID' });
  }
  if (dag.candidate_branch && !String(dag.candidate_branch).startsWith('candidate/')) {
    throw Object.assign(new Error('WORK_DAG_NON_CANDIDATE_BRANCH'), { code: 'WORK_DAG_NON_CANDIDATE_BRANCH' });
  }
  if (!Array.isArray(dag.nodes) || dag.nodes.length === 0) {
    throw Object.assign(new Error('WORK_DAG_NODES_REQUIRED'), { code: 'WORK_DAG_NODES_REQUIRED' });
  }
  const ids = new Set();
  for (const node of dag.nodes) {
    if (!node?.id || ids.has(node.id)) throw Object.assign(new Error('WORK_DAG_NODE_ID_INVALID'), { code: 'WORK_DAG_NODE_ID_INVALID' });
    ids.add(node.id);
    if (!NODE_KINDS.has(node.kind)) throw Object.assign(new Error('WORK_DAG_NODE_KIND_INVALID'), { code: 'WORK_DAG_NODE_KIND_INVALID' });
  }
  for (const node of dag.nodes) {
    for (const dep of node.depends_on || []) {
      if (!ids.has(dep) || dep === node.id) throw Object.assign(new Error('WORK_DAG_DEPENDENCY_INVALID'), { code: 'WORK_DAG_DEPENDENCY_INVALID' });
    }
  }
  assertNoCycles(dag.nodes);
  return true;
}

export function createWorkDag({ id = crypto.randomUUID(), jobId, goal, conversationId = null, candidateBranch = null, candidateSha = null, nodes = [] } = {}) {
  const dag = {
    schema: 'mel.work-dag',
    version: 1,
    id: String(id),
    job_id: String(jobId || ''),
    goal: String(goal || '').slice(0, 4000),
    conversation_id: String(conversationId || '').trim().slice(0, 200) || null,
    candidate_branch: candidateBranch,
    candidate_sha: candidateSha,
    status: WORK_DAG_STATUS.RUNNING,
    nodes: nodes.map((node) => ({
      id: String(node.id || ''),
      kind: String(node.kind || 'TASK').toUpperCase(),
      depends_on: [...(node.depends_on || [])].map(String),
      idempotent: node.idempotent === true,
      payload: clean(node.payload || {}),
      status: WORK_NODE_STATUS.PENDING,
      attempts: 0,
      result: null,
      artifacts: [],
      error: null,
      teacher_request: null,
      teacher_review: null,
    })),
    artifacts: [],
    audit: [{ event: 'WORK_DAG_CREATED', at: Date.now() }],
    created_at: Date.now(),
    updated_at: Date.now(),
  };
  validateWorkDag(dag);
  return dag;
}

export class DevJobWorkDagStore {
  constructor(repository, jobId) {
    if (!repository || !jobId) throw new Error('WORK_DAG_STORE_CONFIG_REQUIRED');
    this.repository = repository;
    this.jobId = jobId;
  }

  async load() {
    const job = await this.repository.get(this.jobId);
    if (!job) throw Object.assign(new Error('JOB_NOT_FOUND'), { code: 'JOB_NOT_FOUND' });
    const dag = job.result_json?.work_dag || null;
    if (!dag) return null;
    await verifyWorkDag(dag);
    if (dag.job_id !== job.id) throw Object.assign(new Error('WORK_DAG_JOB_MISMATCH'), { code: 'WORK_DAG_JOB_MISMATCH' });
    if (dag.candidate_branch && job.candidate_branch && dag.candidate_branch !== job.candidate_branch) {
      throw Object.assign(new Error('WORK_DAG_BRANCH_MISMATCH'), { code: 'WORK_DAG_BRANCH_MISMATCH' });
    }
    return dag;
  }

  async save(dag) {
    validateWorkDag(dag);
    if (dag.job_id !== this.jobId) throw Object.assign(new Error('WORK_DAG_JOB_MISMATCH'), { code: 'WORK_DAG_JOB_MISMATCH' });
    const signed = await signDag({ ...dag, updated_at: Date.now() });
    const job = await this.repository.get(this.jobId);
    if (!job) throw Object.assign(new Error('JOB_NOT_FOUND'), { code: 'JOB_NOT_FOUND' });
    const result = job.result_json && typeof job.result_json === 'object' ? { ...job.result_json } : {};
    result.work_dag = signed;
    await this.repository.update(this.jobId, { result_json: result });
    return signed;
  }
}

export function createAugmentioWorkExecutor(augmentio) {
  if (!augmentio?.fanOut) throw new Error('AUGMENTIO_REQUIRED');
  return async (node) => augmentio.fanOut({
    capability: node.payload?.capability || 'GENERAL',
    input: node.payload?.input || '',
    context: node.payload?.context || {},
    maxCandidates: node.payload?.maxCandidates || 4,
  });
}

export class WorkDagRunner {
  constructor({ store, executors = {}, expectedCandidateSha = null } = {}) {
    if (!store) throw new Error('WORK_DAG_STORE_REQUIRED');
    this.store = store;
    this.executors = executors;
    this.expectedCandidateSha = expectedCandidateSha;
  }

  assertBinding(dag) {
    if (this.expectedCandidateSha && dag.candidate_sha !== this.expectedCandidateSha) {
      throw Object.assign(new Error('WORK_DAG_CANDIDATE_SHA_MISMATCH'), { code: 'WORK_DAG_CANDIDATE_SHA_MISMATCH' });
    }
  }

  async persist(dag, event, detail = {}) {
    dag.audit = [...(dag.audit || []), clean({ event, at: Date.now(), ...detail })];
    return this.store.save(dag);
  }

  async run(initialDag = null, { maxSteps = Infinity } = {}) {
    // A bounded number of nodes per invocation lets cron resume long jobs
    // without keeping a single HTTP request or Worker alive for the whole job.
    const budget = maxSteps === Infinity ? Infinity : Math.max(1, Math.min(16, Number(maxSteps) || 1));
    let completedNow = 0;
    let dag = initialDag || await this.store.load();
    if (!dag) throw Object.assign(new Error('WORK_DAG_NOT_FOUND'), { code: 'WORK_DAG_NOT_FOUND' });
    this.assertBinding(dag);

    for (const node of dag.nodes) {
      if (node.status !== WORK_NODE_STATUS.RUNNING) continue;
      if (!node.idempotent) {
        node.status = WORK_NODE_STATUS.BLOCKED;
        node.error = 'INTERRUPTED_NON_IDEMPOTENT_NODE';
        dag.status = WORK_DAG_STATUS.BLOCKED;
        return this.persist(dag, 'WORK_DAG_FAIL_CLOSED_ON_INTERRUPTED_NODE', { node_id: node.id });
      }
      node.status = WORK_NODE_STATUS.PENDING;
      node.result = null;
      node.artifacts = [];
      dag.artifacts = (dag.artifacts || []).filter((item) => item?.node_id !== node.id);
      node.error = null;
      dag = await this.persist(dag, 'WORK_NODE_RECOVERED_FOR_RETRY', { node_id: node.id });
    }

    while (true) {
      if (dag.nodes.every((node) => node.status === WORK_NODE_STATUS.COMPLETED)) {
        dag.status = WORK_DAG_STATUS.COMPLETED;
        return this.persist(dag, 'WORK_DAG_COMPLETED');
      }
      if (dag.nodes.some((node) => node.status === WORK_NODE_STATUS.WAITING_TEACHER)) {
        dag.status = WORK_DAG_STATUS.WAITING;
        return this.store.save(dag);
      }
      if (dag.nodes.some((node) => [WORK_NODE_STATUS.FAILED, WORK_NODE_STATUS.BLOCKED].includes(node.status))) {
        dag.status = WORK_DAG_STATUS.BLOCKED;
        return this.store.save(dag);
      }

      const ready = dag.nodes.find((node) => node.status === WORK_NODE_STATUS.PENDING &&
        (node.depends_on || []).every((dep) => dag.nodes.find((candidate) => candidate.id === dep)?.status === WORK_NODE_STATUS.COMPLETED));
      if (!ready) {
        dag.status = WORK_DAG_STATUS.BLOCKED;
        return this.persist(dag, 'WORK_DAG_NO_RUNNABLE_NODE');
      }

      ready.status = WORK_NODE_STATUS.RUNNING;
      ready.attempts += 1;
      dag.status = WORK_DAG_STATUS.RUNNING;
      dag = await this.persist(dag, 'WORK_NODE_STARTED', { node_id: ready.id, kind: ready.kind, attempt: ready.attempts });
      const node = dag.nodes.find((candidate) => candidate.id === ready.id);

      try {
        if (node.kind === 'TEACHER') {
          const request = node.payload?.request;
          if (!request || request.type !== 'MEL_TEACHER_REVIEW_REQUEST' || !request.request_id) {
            throw Object.assign(new Error('WORK_TEACHER_REQUEST_REQUIRED'), { code: 'WORK_TEACHER_REQUEST_REQUIRED' });
          }
          node.teacher_request = clean(request);
          node.status = WORK_NODE_STATUS.WAITING_TEACHER;
          dag.status = WORK_DAG_STATUS.WAITING;
          return this.persist(dag, 'WORK_NODE_WAITING_TEACHER', { node_id: node.id, request_id: request.request_id });
        }

        const executor = this.executors[node.kind] || this.executors[node.kind.toLowerCase()];
        if (!executor) throw Object.assign(new Error(`WORK_EXECUTOR_REQUIRED:${node.kind}`), { code: 'WORK_EXECUTOR_REQUIRED' });
        const result = clean(await executor(node, dag));
        const artifacts = Array.isArray(result?.artifacts) ? clean(result.artifacts) : [];
        node.result = result;
        node.artifacts = artifacts;
        dag.artifacts = [
          ...(dag.artifacts || []).filter((item) => item?.node_id !== node.id),
          ...artifacts.map((artifact) => clean({ node_id: node.id, artifact })),
        ].slice(0, 100);
        node.status = WORK_NODE_STATUS.COMPLETED;
        node.error = null;
        dag = await this.persist(dag, 'WORK_NODE_COMPLETED', { node_id: node.id, kind: node.kind, artifact_count: artifacts.length });
        completedNow += 1;
        if (completedNow >= budget && dag.nodes.some(item => item.status !== WORK_NODE_STATUS.COMPLETED)) {
          return this.persist(dag, 'WORK_DAG_YIELDED_FOR_RESUME', { completed_now: completedNow, budget });
        }
      } catch (error) {
        node.status = WORK_NODE_STATUS.FAILED;
        node.error = String(error?.code || error?.message || error).slice(0, 1000);
        dag.status = WORK_DAG_STATUS.BLOCKED;
        return this.persist(dag, 'WORK_NODE_FAILED', { node_id: node.id, code: node.error });
      }
    }
  }

  async submitTeacherReply(nodeId, review) {
    let dag = await this.store.load();
    if (!dag) throw Object.assign(new Error('WORK_DAG_NOT_FOUND'), { code: 'WORK_DAG_NOT_FOUND' });
    this.assertBinding(dag);
    const node = dag.nodes.find((candidate) => candidate.id === nodeId);
    if (!node || node.status !== WORK_NODE_STATUS.WAITING_TEACHER || !node.teacher_request) {
      throw Object.assign(new Error('WORK_TEACHER_NODE_NOT_WAITING'), { code: 'WORK_TEACHER_NODE_NOT_WAITING' });
    }
    const applied = applyTeacherReview(node.teacher_request, review);
    node.teacher_review = clean(applied);
    if (!applied.development_allowed) {
      node.status = WORK_NODE_STATUS.BLOCKED;
      node.error = `TEACHER_${applied.verdict}`;
      dag.status = WORK_DAG_STATUS.BLOCKED;
      return this.persist(dag, 'WORK_TEACHER_REVIEW_BLOCKED', { node_id: node.id, request_id: applied.request_id, verdict: applied.verdict });
    }
    node.status = WORK_NODE_STATUS.COMPLETED;
    node.result = clean(applied);
    node.error = null;
    dag = await this.persist(dag, 'WORK_TEACHER_REVIEW_APPLIED', { node_id: node.id, request_id: applied.request_id, verdict: applied.verdict });
    return this.run(dag);
  }
}

// MEL-FOUNDER-05: a Work mission is complete only with a persisted request,
// an execution event for every node, at least one artifact and an intact
// integrity hash. A merely enqueued DAG never completes the mission.
export async function workMissionReceipt(dag) {
  const reasons = [];
  const audit = Array.isArray(dag?.audit) ? dag.audit : [];
  const nodes = Array.isArray(dag?.nodes) ? dag.nodes : [];
  if (!audit.some(row => row?.event === 'WORK_DAG_CREATED')) reasons.push('WORK_REQUEST_NOT_PERSISTED');
  if (!nodes.length || nodes.every(node => node.status === WORK_NODE_STATUS.PENDING)) reasons.push('WORK_ENQUEUED_ONLY');
  const executed = new Set(audit.filter(row => row?.event === 'WORK_NODE_COMPLETED' || row?.event === 'WORK_TEACHER_REVIEW_APPLIED').map(row => row.node_id));
  if (dag?.status !== WORK_DAG_STATUS.COMPLETED || nodes.some(node => node.status !== WORK_NODE_STATUS.COMPLETED)) reasons.push('WORK_NOT_COMPLETED');
  else if (nodes.some(node => node.kind !== 'TEACHER' && !executed.has(node.id))) reasons.push('WORK_EXECUTION_NOT_RECORDED');
  if (!(Array.isArray(dag?.artifacts) && dag.artifacts.length)) reasons.push('WORK_ARTIFACT_REQUIRED');
  let intact = false;
  try { intact = Boolean(dag) && await verifyWorkDag(dag) === true; } catch { intact = false; }
  if (!intact) reasons.push('WORK_INTEGRITY_INVALID');
  return { schema: 'mel.work-mission-receipt/v1', status: reasons.length ? 'NOT_COMPLETED' : 'COMPLETED',
    job_id: dag?.job_id || null, work_dag_id: dag?.id || null, artifacts: (dag?.artifacts || []).length, reasons };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { D1DevJobRepository } from '../src/dev/d1-dev-job-repository.js';
import { createTeacherReviewRequest } from '../src/teachers/teacher-request.js';
import {
  createWorkDag,
  DevJobWorkDagStore,
  WorkDagRunner,
  createAugmentioWorkExecutor,
  WORK_DAG_STATUS,
  WORK_NODE_STATUS,
  verifyWorkDag,
} from '../src/work/work-dag.js';
import { completeTeacherCouncil, teacherReply, TEST_CANDIDATE_BRANCH, TEST_CANDIDATE_SHA } from './helpers/teacher-review-fixtures.mjs';

function council() { return completeTeacherCouncil(); }

function teacherRequest() {
  return createTeacherReviewRequest({
    goal: 'Prouver la reprise Work de MEL',
    council: council(),
    inspection: { status: 'COMPLETE', evidence: [{ path: 'src/work/work-dag.js' }] },
    spec: { scope: 'bounded-test' },
  });
}

async function setup(jobId) {
  const repo = new D1DevJobRepository(null);
  const job = await repo.create({ id: jobId, goal: 'Work DAG resume proof' });
  await repo.update(job.id, { candidate_branch: 'candidate/mel-clean-autonomy' });
  return { repo, job, store: new DevJobWorkDagStore(repo, job.id) };
}

test('general Work DAG executes dependencies, .augmentio, waits for Teacher, then resumes without duplicate work', async () => {
  const { store, job } = await setup(`work-e2e-${crypto.randomUUID()}`);
  const request = teacherRequest();
  let augmentioCalls = 0;
  let taskCalls = 0;
  const augmentio = {
    async fanOut(input) {
      augmentioCalls += 1;
      assert.equal(input.capability, 'GENERAL');
      return { best: { text: 'bounded council result' }, candidates: [{ text: 'bounded council result' }] };
    },
  };
  const taskExecutor = async (node) => {
    taskCalls += 1;
    return { completed: node.id };
  };
  const dag = createWorkDag({
    jobId: job.id,
    goal: 'Council -> task -> Teacher -> continuation',
    candidateBranch: 'candidate/mel-clean-autonomy',
    candidateSha: TEST_CANDIDATE_SHA,
    nodes: [
      { id: 'council', kind: 'AUGMENTIO', idempotent: true, payload: { input: 'state of play', capability: 'GENERAL', maxCandidates: 2 } },
      { id: 'inspect', kind: 'TASK', depends_on: ['council'], idempotent: true },
      { id: 'teacher', kind: 'TEACHER', depends_on: ['inspect'], payload: { request } },
      { id: 'continue', kind: 'TASK', depends_on: ['teacher'], idempotent: true },
    ],
  });
  await store.save(dag);

  const firstRunner = new WorkDagRunner({
    store,
    expectedCandidateSha: TEST_CANDIDATE_SHA,
    executors: { AUGMENTIO: createAugmentioWorkExecutor(augmentio), TASK: taskExecutor },
  });
  const waiting = await firstRunner.run();
  assert.equal(waiting.status, WORK_DAG_STATUS.WAITING);
  assert.equal(waiting.nodes.find((n) => n.id === 'teacher').status, WORK_NODE_STATUS.WAITING_TEACHER);
  assert.equal(augmentioCalls, 1);
  assert.equal(taskCalls, 1);

  const restartedRunner = new WorkDagRunner({
    store,
    expectedCandidateSha: TEST_CANDIDATE_SHA,
    executors: { AUGMENTIO: createAugmentioWorkExecutor(augmentio), TASK: taskExecutor },
  });
  const stillWaiting = await restartedRunner.run();
  assert.equal(stillWaiting.status, WORK_DAG_STATUS.WAITING);
  assert.equal(augmentioCalls, 1, 'completed augmentio node must not run again after restart');
  assert.equal(taskCalls, 1, 'completed task node must not run again after restart');

  await assert.rejects(
    () => restartedRunner.submitTeacherReply('teacher', teacherReply('wrong')),
    (error) => error?.code === 'TEACHER_REVIEW_REQUEST_MISMATCH',
  );

  const complete = await restartedRunner.submitTeacherReply('teacher', {
    ...teacherReply(request.request_id, { feedback: 'Proceed with bounded implementation.' }),
  });
  assert.equal(complete.status, WORK_DAG_STATUS.COMPLETED);
  assert.equal(complete.nodes.every((n) => n.status === WORK_NODE_STATUS.COMPLETED), true);
  assert.equal(augmentioCalls, 1);
  assert.equal(taskCalls, 2, 'only the post-Teacher continuation should execute');
  await verifyWorkDag(complete);
});

test('interrupted idempotent Work node is recovered from checkpoint and retried once', async () => {
  const { store, job } = await setup(`work-resume-${crypto.randomUUID()}`);
  let calls = 0;
  let dag = createWorkDag({
    jobId: job.id,
    candidateBranch: 'candidate/mel-clean-autonomy',
    candidateSha: 'def5678',
    goal: 'Recover interrupted safe work',
    nodes: [{ id: 'safe', kind: 'TASK', idempotent: true }],
  });
  dag.nodes[0].status = WORK_NODE_STATUS.RUNNING;
  dag.nodes[0].attempts = 1;
  dag = await store.save(dag);

  const runner = new WorkDagRunner({
    store,
    expectedCandidateSha: 'def5678',
    executors: { TASK: async () => { calls += 1; return { ok: true }; } },
  });
  const result = await runner.run();
  assert.equal(result.status, WORK_DAG_STATUS.COMPLETED);
  assert.equal(result.nodes[0].attempts, 2);
  assert.equal(calls, 1);
  assert.equal(result.audit.some((entry) => entry.event === 'WORK_NODE_RECOVERED_FOR_RETRY'), true);
});

test('interrupted non-idempotent node fails closed instead of risking duplicate side effects', async () => {
  const { store, job } = await setup(`work-failclosed-${crypto.randomUUID()}`);
  let calls = 0;
  let dag = createWorkDag({
    jobId: job.id,
    candidateBranch: 'candidate/mel-clean-autonomy',
    candidateSha: '789abcd',
    goal: 'Do not duplicate side effects',
    nodes: [{ id: 'unsafe', kind: 'TASK', idempotent: false }],
  });
  dag.nodes[0].status = WORK_NODE_STATUS.RUNNING;
  dag.nodes[0].attempts = 1;
  await store.save(dag);

  const runner = new WorkDagRunner({
    store,
    expectedCandidateSha: '789abcd',
    executors: { TASK: async () => { calls += 1; return { ok: true }; } },
  });
  const result = await runner.run();
  assert.equal(result.status, WORK_DAG_STATUS.BLOCKED);
  assert.equal(result.nodes[0].status, WORK_NODE_STATUS.BLOCKED);
  assert.equal(result.nodes[0].error, 'INTERRUPTED_NON_IDEMPOTENT_NODE');
  assert.equal(calls, 0);
});

test('Work DAG binding, graph validity and integrity fail closed', async () => {
  const { store, repo, job } = await setup(`work-integrity-${crypto.randomUUID()}`);
  assert.throws(
    () => createWorkDag({ jobId: job.id, candidateBranch: 'main', nodes: [{ id: 'x', kind: 'TASK' }] }),
    (error) => error?.code === 'WORK_DAG_NON_CANDIDATE_BRANCH',
  );
  assert.throws(
    () => createWorkDag({ jobId: job.id, nodes: [
      { id: 'a', kind: 'TASK', depends_on: ['b'] },
      { id: 'b', kind: 'TASK', depends_on: ['a'] },
    ] }),
    (error) => error?.code === 'WORK_DAG_CYCLE',
  );

  const dag = createWorkDag({
    jobId: job.id,
    candidateBranch: 'candidate/mel-clean-autonomy',
    candidateSha: 'feed123',
    goal: 'Integrity',
    nodes: [{ id: 'x', kind: 'TASK', idempotent: true }],
  });
  const saved = await store.save(dag);
  const mismatched = new WorkDagRunner({ store, expectedCandidateSha: 'different', executors: { TASK: async () => ({ ok: true }) } });
  await assert.rejects(() => mismatched.run(), (error) => error?.code === 'WORK_DAG_CANDIDATE_SHA_MISMATCH');

  const jobState = await repo.get(job.id);
  const tampered = structuredClone(jobState.result_json);
  tampered.work_dag.nodes[0].status = WORK_NODE_STATUS.COMPLETED;
  await repo.update(job.id, { result_json: tampered });
  await assert.rejects(() => store.load(), (error) => error?.code === 'WORK_DAG_INTEGRITY_MISMATCH');
  assert.ok(saved.integrity_sha256);
});

// MEL-FOUNDER-05: simulated authorized providers persist request, execution,
// artifact and receipt; an enqueue alone never completes the mission.
test('a simulated Work mission persists request, execution, artifact and receipt; an enqueue alone is not completion', async () => {
  const { workMissionReceipt } = await import('../src/work/work-dag.js');
  const { store, job } = await setup(`work-receipt-${crypto.randomUUID()}`);
  const dag = createWorkDag({ jobId: job.id, goal: 'Simulated provider mission', candidateBranch: 'candidate/mel-clean-autonomy', candidateSha: TEST_CANDIDATE_SHA,
    nodes: [
      { id: 'fetch', kind: 'TASK', idempotent: true },
      { id: 'write', kind: 'TASK', depends_on: ['fetch'], idempotent: true },
    ] });
  await store.save(dag);
  const enqueued = await workMissionReceipt(await store.load());
  assert.equal(enqueued.status, 'NOT_COMPLETED');
  assert.ok(enqueued.reasons.includes('WORK_ENQUEUED_ONLY'));
  const providerCalls = [];
  const runner = new WorkDagRunner({ store, executors: { TASK: async node => {
    providerCalls.push(node.id);
    return { provider: 'simulated-authorized', artifacts: [{ name: `${node.id}.json`, sha256: 'a'.repeat(64) }] };
  } } });
  const done = await runner.run(await store.load());
  assert.equal(done.status, WORK_DAG_STATUS.COMPLETED);
  assert.deepEqual(providerCalls, ['fetch', 'write']);
  const persisted = await store.load();
  const receipt = await workMissionReceipt(persisted);
  assert.equal(receipt.status, 'COMPLETED', JSON.stringify(receipt.reasons));
  assert.equal(receipt.artifacts, 2);
  assert.equal(receipt.job_id, job.id);
  const tampered = await workMissionReceipt({ ...persisted, artifacts: [] });
  assert.ok(tampered.reasons.includes('WORK_ARTIFACT_REQUIRED'));
  assert.ok(tampered.reasons.includes('WORK_INTEGRITY_INVALID'));
});
